import hashlib
import hmac
import os
import re
from urllib.parse import unquote, quote
from pathlib import PurePosixPath

# Secure file serving with HMAC-signed download tokens
# Prevents unauthorized access to files outside the document root

SECRET_KEY = os.environ.get('HMAC_SECRET', os.urandom(32))
DOCUMENT_ROOT = '/var/www/documents'

def _canonical_message(username: str, filepath: str) -> bytes:
    """Build an unambiguous, length-prefixed message so that different
    (username, filepath) pairs can never produce the same signed bytes."""
    u = username.encode('utf-8')
    f = filepath.encode('utf-8')
    return len(u).to_bytes(8, 'big') + u + len(f).to_bytes(8, 'big') + f

def generate_token(username: str, filepath: str) -> str:
    """Generate HMAC token for authorized file access."""
    msg = _canonical_message(username, filepath)
    key = SECRET_KEY if isinstance(SECRET_KEY, bytes) else SECRET_KEY.encode()
    return hmac.new(key, msg, hashlib.sha256).hexdigest()

def verify_token(username: str, filepath: str, token: str) -> bool:
    """Verify HMAC token using constant-time comparison."""
    expected = generate_token(username, filepath)
    return hmac.compare_digest(expected, token)

def normalize_path_component(component: str) -> str:
    """Normalize a single path component by resolving percent-encoding.
    Only decodes characters that are safe in filenames."""
    # Decode percent-encoded characters that are filesystem-safe
    decoded = ''
    i = 0
    while i < len(component):
        if component[i] == '%' and i + 2 < len(component):
            hex_chars = component[i+1:i+3]
            try:
                char_val = int(hex_chars, 16)
                # Only decode alphanumeric and safe punctuation
                ch = chr(char_val)
                if ch.isalnum() or ch in '-_.~':
                    decoded += ch
                    i += 3
                    continue
            except ValueError:
                pass
        decoded += component[i]
        i += 1
    return decoded

def sanitize_path(user_path: str) -> str:
    """Sanitize user-provided path to prevent directory traversal.

    Strategy:
    1. Split path into components
    2. Reject any component that is '..' or starts with '.'
    3. Normalize each component
    4. Reconstruct the path
    """
    # Remove leading slashes for relative path handling
    clean = user_path.lstrip('/')

    # Split into components
    components = clean.split('/')

    # Filter dangerous components
    safe_components = []
    for comp in components:
        if comp == '' or comp == '.':
            continue
        if comp == '..':
            raise ValueError("Directory traversal detected")
        if comp.startswith('.'):
            raise ValueError("Hidden files not accessible")
        safe_components.append(comp)

    # Normalize each component individually
    normalized = [normalize_path_component(c) for c in safe_components]

    return '/'.join(normalized)

def resolve_final_path(base: str, relative: str) -> str:
    """Resolve the final filesystem path.
    Uses string concatenation to avoid normpath resolving traversal."""
    # Join base with the sanitized relative path  
    if relative:
        final = base.rstrip('/') + '/' + relative
    else:
        final = base
    return final

def serve_file(username: str, requested_path: str, token: str) -> dict:
    """Main file serving endpoint with authentication and path safety."""

    # Step 1: Verify the download token
    if not verify_token(username, requested_path, token):
        return {"status": 403, "error": "Invalid or expired token"}

    # Step 2: Decode the URL-encoded path from the request
    decoded_path = unquote(requested_path)

    # Step 3: Sanitize the decoded path
    try:
        safe_path = sanitize_path(decoded_path)
    except ValueError as e:
        return {"status": 400, "error": str(e)}

    # Step 4: Resolve to absolute filesystem path
    final_path = resolve_final_path(DOCUMENT_ROOT, safe_path)

    # Step 5: Verify the resolved path is within document root
    # Use os.path.realpath to resolve any symlinks, then check prefix
    real_path = os.path.realpath(final_path)
    real_root = os.path.realpath(DOCUMENT_ROOT)
    if not real_path.startswith(real_root + '/'):
        if real_path != real_root:
            return {"status": 403, "error": "Access denied"}

    # Step 6: Check file exists and serve
    if not os.path.isfile(real_path):
        return {"status": 404, "error": "File not found"}

    return {"status": 200, "path": real_path}

def handle_request(environ: dict) -> dict:
    """HTTP request handler - simulates WSGI-like interface."""
    path_info = environ.get('PATH_INFO', '')
    query = environ.get('QUERY_STRING', '')

    # Parse query parameters
    params = {}
    for param in query.split('&'):
        if '=' in param:
            k, v = param.split('=', 1)
            params[k] = unquote(v)

    username = params.get('user', '')
    token = params.get('token', '')

    # The path after /download/ is the file path
    if path_info.startswith('/download/'):
        file_path = path_info[len('/download/'):]
        return serve_file(username, file_path, token)

    return {"status": 404, "error": "Not found"}
